using Xunit;

namespace Cache.Tests;

public class LruCacheTests
{
    [Fact]
    public void EvictsOldestWhenFull()
    {
        var c = new LruCache<string, int>(2);
        c.Put("a", 1);
        c.Put("b", 2);
        c.Put("c", 3);
        Assert.False(c.TryGet("a", out _), "a should have been evicted");
    }

    [Fact]
    public void GetRefreshesEntry()
    {
        var c = new LruCache<string, int>(2);
        c.Put("a", 1);
        c.Put("b", 2);
        c.TryGet("a", out _);
        c.Put("c", 3);
        Assert.True(c.TryGet("a", out var v));
        Assert.Equal(1, v);
    }
}

