using System;
using Xunit;

namespace Auth.Tests;

public class TokenVerifierTests
{
    private readonly TokenIssuer _issuer = new("secret");
    private readonly TokenVerifier _verifier = new("secret");

    [Fact]
    public void ExpiredTokenIsRejected()
    {
        var token = _issuer.Issue("alice", TimeSpan.FromMinutes(1));
        var later = DateTimeOffset.UtcNow.AddMinutes(2);
        Assert.Throws<ExpiredTokenException>(() => _verifier.Verify(token, later));
    }

    [Fact]
    public void TamperedTokenIsRejected()
    {
        var token = _issuer.Issue("alice", TimeSpan.FromHours(1)) + "x";
        Assert.Throws<BadSignatureException>(() => _verifier.Verify(token, DateTimeOffset.UtcNow));
    }
}

